#!/usr/bin/env python3
"""
check-author-voice-populated.py

Deterministic precondition check for AUTHOR_VOICE.md: is it missing, an
unpopulated stub (the exact placeholder shape written by init/voice-distiller
before any real content has been seeded), or does it contain real voice
content?

AUTHOR_VOICE.md has four required sections, each of which is a stub until
populated by Stage 1 (voice-miner/voice-distiller) or Stage 2 (the `:voice`
interview):

    ## Core voice
    ## Terminology
    ## Academic-specific
    ## Non-fiction-book-specific

A section counts as still-a-stub if, after stripping its heading, its body
is empty or consists ONLY of one of the known placeholder lines (matched
case-insensitively, ignoring surrounding whitespace):

    _Empty._
    _Empty. Populated by Stage 1 miner and Stage 2 interview._

As a deterministic backstop against a section that was "populated" with a
single throwaway word or a copy-pasted placeholder variant, the file is also
rejected if its total substantive word count -- all body text outside
headings, the leading blockquote status lines, and placeholder lines -- is
below a small threshold (default 30 words).

The file is considered POPULATED only if:
  1. It exists and is non-empty, AND
  2. All four required sections are present, AND
  3. None of the four sections is still a stub (per the placeholder match
     above), AND
  4. The substantive word count meets the minimum threshold.

Usage:
    python3 check-author-voice-populated.py [path-to-AUTHOR_VOICE.md]

    Path defaults to AUTHOR_VOICE.md in the current directory.

Exit code: 0 if populated, 1 if missing or still a stub.
Dependency-free (Python 3 stdlib only).
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

REQUIRED_SECTIONS = [
    "Core voice",
    "Terminology",
    "Academic-specific",
    "Non-fiction-book-specific",
]

MIN_SUBSTANTIVE_WORDS = 30

PLACEHOLDER_LINES = {
    "_empty._",
    "_empty. populated by stage 1 miner and stage 2 interview._",
}

SECTION_HEADING_RE = re.compile(r"^##\s+(.+?)\s*$", re.MULTILINE)
BLOCKQUOTE_LINE_RE = re.compile(r"^>.*$", re.MULTILINE)
H1_LINE_RE = re.compile(r"^#\s.*$", re.MULTILINE)


def extract_sections(text: str) -> dict[str, str]:
    """Map each '## Heading' to the raw text between it and the next heading.

    Matching against REQUIRED_SECTIONS is by prefix, not exact equality:
    the real AUTHOR_VOICE.md template has "## Core voice (cross-project)"
    for the first section, so a heading counts as satisfying a required
    section name if the heading starts with that name.
    """
    matches = list(SECTION_HEADING_RE.finditer(text))
    sections: dict[str, str] = {}
    for i, m in enumerate(matches):
        name = m.group(1).strip()
        start = m.end()
        end = matches[i + 1].start() if i + 1 < len(matches) else len(text)
        body = text[start:end].strip()
        for required in REQUIRED_SECTIONS:
            if name.lower().startswith(required.lower()) and required not in sections:
                sections[required] = body
                break
        else:
            sections[name] = body
    return sections


def is_stub_body(body: str) -> bool:
    if not body:
        return True
    return body.strip().lower() in PLACEHOLDER_LINES


def substantive_word_count(text: str) -> int:
    """Word count of body text, excluding headings, blockquote status lines,
    and known placeholder lines."""
    stripped = BLOCKQUOTE_LINE_RE.sub("", text)
    stripped = H1_LINE_RE.sub("", stripped)
    stripped = SECTION_HEADING_RE.sub("", stripped)
    lines = [
        line
        for line in stripped.splitlines()
        if line.strip().lower() not in PLACEHOLDER_LINES
    ]
    words = re.findall(r"\S+", "\n".join(lines))
    return len(words)


def check(path: Path) -> tuple[bool, str]:
    if not path.exists():
        return (
            False,
            f"MISSING: {path} does not exist. Run /academic-writer:voice first.",
        )

    try:
        text = path.read_text(encoding="utf-8", errors="strict")
    except UnicodeDecodeError as e:
        return False, f"UNREADABLE: {path} is not valid UTF-8 ({e})."

    if not text.strip():
        return (
            False,
            f"EMPTY: {path} exists but is empty. Run /academic-writer:voice first.",
        )

    sections = extract_sections(text)

    missing = [s for s in REQUIRED_SECTIONS if s not in sections]
    if missing:
        return False, (
            f"MALFORMED: {path} is missing required section(s): {', '.join(missing)}. "
            "Run /academic-writer:voice to seed it."
        )

    stub_sections = [s for s in REQUIRED_SECTIONS if is_stub_body(sections[s])]
    if stub_sections:
        return False, (
            f"STUB: {path} still has unpopulated placeholder section(s): "
            f"{', '.join(stub_sections)}. Run /academic-writer:voice first."
        )

    word_count = substantive_word_count(text)
    if word_count < MIN_SUBSTANTIVE_WORDS:
        return False, (
            f"STUB: {path} has only {word_count} substantive word(s), below the "
            f"minimum of {MIN_SUBSTANTIVE_WORDS}. Run /academic-writer:voice first."
        )

    return (
        True,
        f"POPULATED: {path} has {word_count} substantive word(s) across all four sections.",
    )


def main(argv: list[str]) -> int:
    path = Path(argv[0]) if argv else Path("AUTHOR_VOICE.md")
    ok, reason = check(path)
    print(reason)
    return 0 if ok else 1


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
